import type { Question } from '../../lib/types'

export const database_performance_questions: Question[] = [
  { id: 'd3-db-001', domain: 3, topics: ['DynamoDB', 'on-demand', 'provisioned', 'capacity modes'], type: 'single', stem: 'A DynamoDB table experiences unpredictable traffic with occasional bursts and long idle periods. Which capacity mode avoids throttling while minimizing costs?', options: [{ id: 'A', text: 'Provisioned capacity with Auto Scaling' }, { id: 'B', text: 'On-Demand capacity — automatically scales to accommodate traffic, no capacity planning needed' }, { id: 'C', text: 'Provisioned capacity with no Auto Scaling' }, { id: 'D', text: 'DynamoDB Streams' }], correct: ['B'], explanation: 'DynamoDB On-Demand mode automatically scales read/write throughput with no provisioning. Charges per request. Best for truly unpredictable traffic. For predictable traffic, Provisioned + Auto Scaling is often cheaper.', distractors: { A: 'Provisioned + Auto Scaling reacts to traffic changes with some lag — burst traffic can cause throttling during scale-out. On-Demand handles instantaneous bursts.', C: 'Fixed provisioned capacity will throttle during bursts — expensive if over-provisioned.', D: 'DynamoDB Streams is for change data capture — not a capacity mode.' } },
  { id: 'd3-db-002', domain: 3, topics: ['DynamoDB', 'read capacity', 'strongly consistent'], type: 'single', stem: 'A DynamoDB application requires strongly consistent reads. How does this affect Read Capacity Unit (RCU) consumption?', options: [{ id: 'A', text: 'Strongly consistent reads consume 0.5 RCU per 4 KB (cheaper)' }, { id: 'B', text: 'Strongly consistent reads consume 1 RCU per 4 KB — twice as many RCUs as eventually consistent reads (0.5 RCU)' }, { id: 'C', text: 'Strongly consistent reads are the same cost as eventually consistent' }, { id: 'D', text: 'Strongly consistent reads are not supported by DynamoDB' }], correct: ['B'], explanation: 'Eventually consistent reads: 0.5 RCU per 4 KB. Strongly consistent reads: 1 RCU per 4 KB — twice the cost. For read-heavy applications, using eventually consistent reads where acceptable reduces costs and increases throughput.', distractors: { A: '0.5 RCU is for eventually consistent reads — not strongly consistent.', C: 'Strongly consistent reads cost 2x more — significant for capacity planning.', D: 'DynamoDB supports both strongly consistent and eventually consistent reads.' } },
  { id: 'd3-db-003', domain: 3, topics: ['DynamoDB', 'GSI', 'LSI'], type: 'single', stem: 'A DynamoDB table has OrderId (partition key) and CustomerId (attribute). Queries must filter by CustomerId efficiently. What enables CustomerId-based queries?', options: [{ id: 'A', text: 'Scan the entire table with a FilterExpression' }, { id: 'B', text: 'Global Secondary Index (GSI) with CustomerId as the partition key — enables efficient query by CustomerId' }, { id: 'C', text: 'Local Secondary Index (LSI) on CustomerId' }, { id: 'D', text: 'DynamoDB Streams' }], correct: ['B'], explanation: 'A GSI with CustomerId as the partition key allows querying all orders for a customer efficiently. GSIs can have a different partition key from the base table. Can be added to existing tables (unlike LSIs which must be created with the table).', distractors: { A: 'Table scans read every item — expensive and slow, especially as table grows. O(n) cost.', C: 'LSIs must share the same partition key (OrderId) as the base table — CustomerId as the LSI partition key is not possible.', D: 'Streams capture item changes — not a query mechanism.' } },
  { id: 'd3-db-004', domain: 3, topics: ['ElastiCache', 'Redis', 'caching patterns'], type: 'single', stem: 'An application queries an RDS database frequently for the same data (product catalog). Response times are high due to database load. What caching strategy adds ElastiCache Redis most effectively?', options: [{ id: 'A', text: 'Write-through caching' }, { id: 'B', text: 'Lazy loading (cache-aside) — check cache first, query DB on miss, store result in cache with TTL' }, { id: 'C', text: 'Write-behind caching' }, { id: 'D', text: 'Read-through caching' }], correct: ['B'], explanation: 'Lazy loading: check cache → cache hit returns immediately → cache miss queries DB, stores result in cache. First call is slow (DB query), subsequent calls are fast (cache hit). TTL ensures data freshness. Most common caching pattern for read-heavy workloads.', distractors: { A: 'Write-through writes to cache AND DB on every write — adds write latency but ensures cache is always fresh.', C: 'Write-behind writes to cache first, then async to DB — may lose data on failure, complex to implement.', D: 'Read-through has the cache fetch data from DB on miss (automatically) — similar to lazy loading but the cache is responsible, not the application.' } },
  { id: 'd3-db-005', domain: 3, topics: ['DynamoDB', 'partitioning', 'hot partition'], type: 'single', stem: 'A DynamoDB table has StatusCode as the partition key. One status value ("PENDING") gets 90% of the writes. Performance is poor for this item. What is the root cause?', options: [{ id: 'A', text: 'DynamoDB tables have a maximum of 10 partitions' }, { id: 'B', text: 'Hot partition problem — one partition key value concentrates too much traffic on a single partition, hitting partition limits' }, { id: 'C', text: 'PENDING is a reserved word in DynamoDB' }, { id: 'D', text: 'DynamoDB doesn\'t support string partition keys' }], correct: ['B'], explanation: 'DynamoDB partitions data by partition key. Each partition has a throughput limit. If most traffic goes to one key (PENDING), that partition gets throttled while others are idle. Solutions: add a random suffix (PENDING-1 through PENDING-N) or use write sharding.', distractors: { A: 'DynamoDB automatically creates more partitions as needed — no artificial limit.', C: 'PENDING is not a reserved word in DynamoDB — it\'s a valid partition key value.', D: 'DynamoDB supports strings as partition keys.' } },
  { id: 'd3-db-006', domain: 3, topics: ['ElastiCache', 'Redis', 'Memcached'], type: 'single', stem: 'An application needs a caching solution that supports complex data structures (sorted sets, hashes) and data persistence. Which ElastiCache engine should be chosen?', options: [{ id: 'A', text: 'Memcached — simpler, multi-threaded, no persistence' }, { id: 'B', text: 'Redis — rich data types (strings, hashes, lists, sets, sorted sets), persistence, replication, pub/sub' }, { id: 'C', text: 'Both Memcached and Redis support persistence equally' }, { id: 'D', text: 'DynamoDB DAX' }], correct: ['B'], explanation: 'Redis supports complex data types (sorted sets for leaderboards, hashes, lists, bitmaps), persistence (RDB/AOF), replication, and Lua scripting. Memcached is simpler (key-value strings only) with no persistence.', distractors: { A: 'Memcached doesn\'t support persistence or complex data types — it\'s a simple key-value cache.', C: 'Memcached has no persistence — Redis does. They are not equivalent.', D: 'DynamoDB DAX is a DynamoDB-specific cache — not a general-purpose application cache.' } },
  { id: 'd3-db-007', domain: 3, topics: ['DynamoDB', 'DAX', 'microsecond'], type: 'single', stem: 'A DynamoDB table is read-heavy with millisecond latency requirements that are not being met. What purpose-built DynamoDB cache reduces latency to microseconds?', options: [{ id: 'A', text: 'ElastiCache Redis in front of DynamoDB' }, { id: 'B', text: 'Amazon DynamoDB Accelerator (DAX) — in-memory cache specifically for DynamoDB, reduces latency to microseconds' }, { id: 'C', text: 'DynamoDB Streams with Lambda for pre-computation' }, { id: 'D', text: 'Increase DynamoDB provisioned throughput' }], correct: ['B'], explanation: 'DAX is a fully managed, DynamoDB-compatible in-memory cache providing microsecond latency for read operations. It\'s API-compatible with DynamoDB — no application code changes needed, just point to the DAX cluster endpoint.', distractors: { A: 'ElastiCache Redis requires application code changes to check cache — DAX is DynamoDB API-compatible (transparent).', C: 'Streams + Lambda handles event-driven use cases — not a transparent read cache.', D: 'Higher provisioned throughput improves service capacity — doesn\'t reduce latency to microseconds.' } },
  { id: 'd3-db-008', domain: 3, topics: ['RDS', 'performance', 'parameter tuning'], type: 'single', stem: 'An RDS PostgreSQL database has high wait times on "Client:ClientRead" indicating slow application reads. A DBA suspects connection overhead. What addresses high connection overhead?', options: [{ id: 'A', text: 'Increase max_connections parameter' }, { id: 'B', text: 'Amazon RDS Proxy — connection pooling reduces new connection overhead' }, { id: 'C', text: 'Upgrade to a larger instance type' }, { id: 'D', text: 'Enable Multi-AZ' }], correct: ['B'], explanation: 'ClientRead wait indicates the server is waiting for the client — often slow application code or high connection setup time. RDS Proxy pools connections at the proxy layer, allowing applications to quickly get a pooled connection rather than creating a new TCP+SSL+auth cycle each time.', distractors: { A: 'max_connections allows more connections — doesn\'t reduce per-connection overhead.', C: 'Larger instance has more CPU/memory — doesn\'t reduce connection setup overhead.', D: 'Multi-AZ provides HA — unrelated to connection performance.' } },
  { id: 'd3-db-009', domain: 3, topics: ['DynamoDB', 'transactions', 'ACID'], type: 'single', stem: 'A banking application needs to atomically transfer money between two DynamoDB items (debit one account, credit another). Either both operations succeed or neither does. What DynamoDB feature enables this?', options: [{ id: 'A', text: 'DynamoDB Conditional Writes with two separate requests' }, { id: 'B', text: 'DynamoDB TransactWriteItems — ACID transactions across multiple items, all succeed or all fail' }, { id: 'C', text: 'DynamoDB Batch Write' }, { id: 'D', text: 'DynamoDB Global Tables' }], correct: ['B'], explanation: 'TransactWriteItems supports atomic all-or-nothing operations across up to 100 items (in same or different tables). Either all succeed or all fail with a TransactionCanceledException. Enables ACID-like transactions in DynamoDB.', distractors: { A: 'Conditional writes are per-item atomic — but two separate conditional writes don\'t form an atomic transaction together.', C: 'Batch writes are best-effort — each operation is independent, not transactional.', D: 'Global Tables is for multi-region replication — not transactions.' } },
  { id: 'd3-db-010', domain: 3, topics: ['ElastiCache', 'Redis Cluster', 'sharding'], type: 'single', stem: 'An ElastiCache Redis cluster is nearing memory limits. The dataset needs to be distributed across multiple nodes. What Redis feature enables horizontal scaling?', options: [{ id: 'A', text: 'Redis Replication' }, { id: 'B', text: 'Redis Cluster mode enabled — shards data across multiple primary nodes for horizontal scaling' }, { id: 'C', text: 'Increase node instance size (vertical scaling)' }, { id: 'D', text: 'Redis Read Replicas' }], correct: ['B'], explanation: 'Redis Cluster mode (cluster mode enabled) partitions data across up to 500 shards, each with their own primary and optional replicas. Enables both horizontal scaling (more shards) and high availability (replicas per shard).', distractors: { A: 'Replication creates copies for HA — doesn\'t distribute data across nodes.', C: 'Vertical scaling has instance size limits — cluster mode enables unlimited horizontal scaling.', D: 'Read replicas add read capacity within a single shard — don\'t shard the dataset.' } },
  { id: 'd3-db-011', domain: 3, topics: ['DynamoDB', 'write sharding', 'hot key'], type: 'single', stem: 'A DynamoDB table uses a timestamp as the partition key. All writes go to the most recent timestamp, creating a hot partition. What technique distributes writes?', options: [{ id: 'A', text: 'Use timestamps only — DynamoDB handles hot partitions automatically' }, { id: 'B', text: 'Write sharding — append a random suffix (0-N) to the partition key to distribute across multiple partitions' }, { id: 'C', text: 'Switch to On-Demand capacity' }, { id: 'D', text: 'Use a sort key instead of partition key for timestamps' }], correct: ['B'], explanation: 'Write sharding: append a random number (e.g., 0-9) to the timestamp partition key. Writes distribute across 10 partitions instead of 1. Reads must query all N shards and aggregate — adds read complexity but solves hot partition.', distractors: { A: 'DynamoDB doesn\'t automatically redistribute hot partition traffic — application-level sharding is required.', C: 'On-Demand capacity handles burst traffic better but hot partition limits still apply per partition.', D: 'Sort keys organize data within a partition — they don\'t distribute writes across partitions.' } },
  { id: 'd3-db-012', domain: 3, topics: ['MemoryDB', 'Redis', 'durable'], type: 'single', stem: 'An application uses Redis as its primary database (not just a cache) and requires data durability with microsecond latency. What AWS service provides durable Redis-compatible storage?', options: [{ id: 'A', text: 'ElastiCache Redis with persistence enabled' }, { id: 'B', text: 'Amazon MemoryDB for Redis — durable, strongly consistent, Redis-compatible primary database with microsecond latency' }, { id: 'C', text: 'DynamoDB with DAX' }, { id: 'D', text: 'RDS Redis' }], correct: ['B'], explanation: 'MemoryDB for Redis is designed for Redis as a primary database: durable (data stored in a distributed Multi-AZ transaction log), strongly consistent reads, microsecond read/write latency. Survives cluster restarts without data loss.', distractors: { A: 'ElastiCache Redis AOF persistence can be slow and has recovery limitations — MemoryDB provides stronger durability guarantees with a proper transaction log.', C: 'DynamoDB + DAX is not Redis-compatible — application code would need to change.', D: 'RDS Redis does not exist — RDS supports MySQL, PostgreSQL, Oracle, SQL Server, MariaDB.' } },
  { id: 'd3-db-013', domain: 3, topics: ['Aurora', 'parallel query', 'analytics'], type: 'single', stem: 'An Aurora MySQL database handles both OLTP transactions and analytical queries. Long analytical queries are degrading OLTP performance. What Aurora feature runs analytics queries more efficiently?', options: [{ id: 'A', text: 'Aurora read replicas for queries' }, { id: 'B', text: 'Aurora Parallel Query — pushes query execution to the storage layer, reducing OLTP interference' }, { id: 'C', text: 'Aurora Global Database' }, { id: 'D', text: 'Aurora Multi-AZ' }], correct: ['B'], explanation: 'Aurora Parallel Query offloads analytical query processing to the storage layer nodes, reducing load on the compute layer (primary instance). OLTP workloads see less contention because analytics queries don\'t compete for the buffer pool.', distractors: { A: 'Read replicas offload query processing but still compete for instance resources (CPU, memory) for buffer pool.', C: 'Global Database is for cross-region replication — not analytics offloading.', D: 'Multi-AZ provides HA — not analytics optimization.' } },
  { id: 'd3-db-014', domain: 3, topics: ['DynamoDB', 'TTL', 'expiration'], type: 'single', stem: 'A DynamoDB table stores session data that should automatically expire after 24 hours. What DynamoDB feature handles automatic data expiration?', options: [{ id: 'A', text: 'DynamoDB lifecycle rules' }, { id: 'B', text: 'DynamoDB Time to Live (TTL) — set an expiry epoch timestamp attribute; DynamoDB automatically deletes expired items' }, { id: 'C', text: 'DynamoDB Streams' }, { id: 'D', text: 'Lambda scheduled job to delete old items' }], correct: ['B'], explanation: 'DynamoDB TTL marks items for deletion by specifying an expiry timestamp (Unix epoch) in a designated attribute. Items are deleted automatically within 48 hours after the TTL time passes. Deletion is free and doesn\'t consume WCUs.', distractors: { A: 'DynamoDB doesn\'t have lifecycle rules — TTL is the expiration feature.', C: 'Streams capture item changes (including TTL deletes) — not a deletion mechanism.', D: 'Lambda scheduled deletion works but requires extra infrastructure and consumes WCUs for DeleteItem operations.' } },
  { id: 'd3-db-015', domain: 3, topics: ['RDS', 'read replica', 'performance'], type: 'single', stem: 'An RDS MySQL database handles 80% reads and 20% writes. To improve overall performance, what is the best optimization?', options: [{ id: 'A', text: 'Upgrade to a larger RDS instance' }, { id: 'B', text: 'Add RDS Read Replicas and route read traffic to them — offloads 80% of queries from the primary' }, { id: 'C', text: 'Enable Multi-AZ for read scaling' }, { id: 'D', text: 'Increase max_connections' }], correct: ['B'], explanation: 'For read-heavy workloads, Read Replicas distribute the read load. Route SELECT queries to replicas and DML (INSERT/UPDATE/DELETE) to the primary. Up to 5 read replicas for MySQL.', distractors: { A: 'Vertical scaling helps but has limits and cost — horizontal read scaling via replicas is more scalable.', C: 'Multi-AZ standby doesn\'t serve read traffic — it\'s only for failover.', D: 'max_connections allows more connections — doesn\'t distribute the read load.' } },
  { id: 'd3-db-016', domain: 3, topics: ['DynamoDB', 'query', 'scan', 'performance'], type: 'single', stem: 'A developer writes DynamoDB code using Scan with a FilterExpression to find items by email. With millions of items, performance is very slow. What is the correct approach?', options: [{ id: 'A', text: 'Increase provisioned throughput' }, { id: 'B', text: 'Create a GSI with email as the partition key — enables direct Query instead of Scan' }, { id: 'C', text: 'Use DynamoDB Streams to pre-process results' }, { id: 'D', text: 'Add more WCUs to handle the scan faster' }], correct: ['B'], explanation: 'Scan with FilterExpression reads every item then filters — O(n) cost regardless of matches. A GSI with email as the partition key allows Query operations that read only matching items — O(1) for a single email. Always prefer Query over Scan.', distractors: { A: 'More throughput makes the scan faster but doesn\'t fix the fundamental O(n) inefficiency.', C: 'Streams capture changes — not a query optimization technique.', D: 'More WCUs reduce scan time but still scan all items — costly and still slow for large tables.' } },
  { id: 'd3-db-017', domain: 3, topics: ['ElastiCache', 'Redis', 'data types', 'leaderboard'], type: 'single', stem: 'A gaming application needs a real-time leaderboard that supports incrementing scores and retrieving the top 100 players efficiently. Which ElastiCache Redis data type is ideal?', options: [{ id: 'A', text: 'String (INCR for scores)' }, { id: 'B', text: 'Sorted Set (ZADD, ZRANGE, ZRANGEBYSCORE) — stores members with scores, auto-sorted, O(log N) operations' }, { id: 'C', text: 'Hash (HSET/HGET for player data)' }, { id: 'D', text: 'List (LPUSH/LRANGE for ranking)' }], correct: ['B'], explanation: 'Redis Sorted Sets are perfect for leaderboards: ZADD adds/updates a player\'s score, ZREVRANGE with LIMIT retrieves top N players sorted by score. O(log N) time complexity for all operations. Data stays sorted automatically.', distractors: { A: 'Strings with INCR can increment scores but provide no sorted ordering — getting top 100 requires reading all scores.', C: 'Hashes store player data (name, level) — not sorted score rankings.', D: 'Lists support push/pop but don\'t maintain score ordering automatically.' } },
  { id: 'd3-db-018', domain: 3, topics: ['Aurora', 'endpoints', 'performance'], type: 'single', stem: 'A company has an Aurora cluster with 1 primary and 5 replicas. A reporting application runs complex queries that should be isolated from the OLTP primary. How should connections be routed?', options: [{ id: 'A', text: 'Connect to the writer endpoint for all queries' }, { id: 'B', text: 'Create a custom endpoint pointing to the replicas designated for reporting — isolate reporting traffic from OLTP' }, { id: 'C', text: 'Use the reader endpoint — it distributes to all replicas' }, { id: 'D', text: 'Connect to individual replica instance endpoints' }], correct: ['B'], explanation: 'Aurora custom endpoints allow routing specific workloads to specific replica sets. Create a custom endpoint containing only the high-memory replicas for reporting. Other replicas handle OLTP reads via the reader endpoint. Dedicated replicas for analytics prevent OLTP impact.', distractors: { A: 'Writer endpoint routes to the primary — reporting should not run on the primary.', C: 'The reader endpoint distributes across all replicas — reporting queries could land on OLTP replicas.', D: 'Individual replica endpoints work but require manual management when replicas fail or are added.' } },
  { id: 'd3-db-019', domain: 3, topics: ['DynamoDB', 'capacity units', 'WCU calculation'], type: 'single', stem: 'A DynamoDB table needs to write 1,000 items per second, each item 3 KB in size. How many WCUs are required?', options: [{ id: 'A', text: '1,000 WCUs' }, { id: 'B', text: '3,000 WCUs — each write >1KB and ≤2KB costs 2 WCUs; 3KB item = 3 WCUs; 1,000 items/sec = 3,000 WCUs' }, { id: 'C', text: '500 WCUs' }, { id: 'D', text: '1 WCU per item regardless of size' }], correct: ['B'], explanation: 'WCU calculation: 1 WCU = 1 write per second up to 1 KB. A 3 KB item requires 3 WCUs (round up to nearest KB). For 1,000 items/sec × 3 KB = 3,000 WCUs. For eventual consistency writes, same calculation.', distractors: { A: '1,000 WCUs would only handle 1 KB items at 1,000 items/sec — undersized for 3 KB items.', C: '500 WCUs is half — would handle only 500 items/sec at 1 KB each, not 1,000 at 3 KB.', D: 'WCU consumption scales with item size — 1 KB = 1 WCU, 3 KB = 3 WCUs.' } },
  { id: 'd3-db-020', domain: 3, topics: ['RDS', 'proxy', 'connection pooling', 'Lambda'], type: 'single', stem: 'Why is Amazon RDS Proxy specifically beneficial for serverless Lambda functions connecting to RDS?', options: [{ id: 'A', text: 'Lambda can only connect to RDS through a proxy' }, { id: 'B', text: 'Lambda creates a new DB connection per invocation — Proxy pools connections, preventing connection exhaustion and reducing connection latency' }, { id: 'C', text: 'RDS Proxy provides caching for Lambda results' }, { id: 'D', text: 'RDS Proxy enables Lambda to connect to DynamoDB' }], correct: ['B'], explanation: 'Lambda can have thousands of concurrent instances, each creating a new DB connection. Each TCP+SSL+auth connection takes time and consumes a DB connection slot. Proxy maintains a pool and reuses connections — Lambda instances connect to Proxy quickly, Proxy manages the DB side.', distractors: { A: 'Lambda can connect directly to RDS — Proxy is a recommendation, not a requirement.', C: 'RDS Proxy pools connections — not a query result cache.', D: 'RDS Proxy is for RDS/Aurora — DynamoDB has its own SDK.' } },
  { id: 'd3-db-021', domain: 3, topics: ['DynamoDB', 'projections', 'GSI cost'], type: 'single', stem: 'A DynamoDB table has 50 attributes. A GSI on the table is configured to project ALL attributes. This increases GSI storage costs significantly. What reduces GSI storage cost?', options: [{ id: 'A', text: 'GSIs always project all attributes' }, { id: 'B', text: 'Configure the GSI projection to INCLUDE only the attributes needed by queries — reduces storage of redundant attribute data in the index' }, { id: 'C', text: 'Use fewer GSIs' }, { id: 'D', text: 'Use LSIs instead of GSIs for cheaper projections' }], correct: ['B'], explanation: 'GSI projections: KEYS_ONLY (cheapest — partition + sort keys only), INCLUDE (specific attributes), ALL (all attributes — most expensive). For a 50-attribute table, projecting only 5 needed attributes is much cheaper than ALL.', distractors: { A: 'GSIs support KEYS_ONLY, INCLUDE, and ALL projections — not only ALL.', C: 'Fewer GSIs reduce query flexibility — INCLUDE projection is the targeted optimization.', D: 'LSIs share the base table storage — they don\'t have cheaper projections. Projection type affects cost regardless of index type.' } },
  { id: 'd3-db-022', domain: 3, topics: ['Aurora', 'serverless v2', 'scaling'], type: 'single', stem: 'Aurora Serverless v2 is configured with min ACUs = 0.5 and max ACUs = 128. What is the minimum time it takes to scale from 0.5 ACUs to needed capacity during a traffic burst?', options: [{ id: 'A', text: '5-10 minutes (same as standard Aurora scale-out)' }, { id: 'B', text: 'Near-instantaneous — Aurora Serverless v2 scales in fine-grained increments (0.5 ACU steps) within seconds' }, { id: 'C', text: '30 seconds' }, { id: 'D', text: 'Aurora Serverless v2 can\'t scale that quickly' }], correct: ['B'], explanation: 'Aurora Serverless v2 scales in increments of 0.5 ACUs and responds to load changes within seconds. This is fundamentally different from v1 which had cold start delays. Fine-grained, rapid scaling avoids the latency spikes of coarser scaling.', distractors: { A: '5-10 minutes would be for provisioning new RDS instances — Serverless v2 scales the existing cluster\'s compute in seconds.', C: '30 seconds is too long — Serverless v2 scales within seconds.', D: 'Serverless v2 specifically provides rapid scaling as its core feature.' } },
  { id: 'd3-db-023', domain: 3, topics: ['DynamoDB', 'item size', 'limits'], type: 'single', stem: 'A DynamoDB item is 600 KB in size. What is the maximum item size limit in DynamoDB?', options: [{ id: 'A', text: '256 KB' }, { id: 'B', text: '400 KB — items exceeding this limit must be redesigned or stored partially in S3' }, { id: 'C', text: '1 MB' }, { id: 'D', text: 'No limit' }], correct: ['B'], explanation: 'DynamoDB maximum item size is 400 KB (including all attribute names and values). Large items (documents, binary data) should store the large payload in S3 and store only the S3 reference in DynamoDB.', distractors: { A: '256 KB is not the DynamoDB limit — 400 KB is correct.', C: '1 MB exceeds DynamoDB\'s 400 KB item limit.', D: 'DynamoDB has a 400 KB per item limit — not unlimited.' } },
  { id: 'd3-db-024', domain: 3, topics: ['ElastiCache', 'cluster mode', 'online resharding'], type: 'single', stem: 'An ElastiCache Redis cluster mode enabled cluster is running out of memory. No downtime is acceptable. How can the cluster be scaled out?', options: [{ id: 'A', text: 'Restore the cluster from a backup with more shards' }, { id: 'B', text: 'Online resharding — add shards to the cluster without downtime using ElastiCache\'s live scaling' }, { id: 'C', text: 'Scale up the node instance types' }, { id: 'D', text: 'Add read replicas' }], correct: ['B'], explanation: 'ElastiCache Redis cluster mode supports online resharding (adding or removing shards) without downtime. Data is redistributed across new shards automatically. Applications continue operating during resharding.', distractors: { A: 'Backup restoration requires downtime and may use outdated data — online resharding is the zero-downtime option.', C: 'Scaling up node types increases memory per shard — still limited by a single shard\'s instance size. Adding shards provides more total memory.', D: 'Read replicas add read capacity per shard — don\'t increase total memory capacity across shards.' } },
  { id: 'd3-db-025', domain: 3, topics: ['DynamoDB', 'Streams', 'event-driven'], type: 'single', stem: 'A company wants to trigger an action every time a DynamoDB item is created or updated. What feature enables this event-driven processing?', options: [{ id: 'A', text: 'DynamoDB scheduled queries' }, { id: 'B', text: 'DynamoDB Streams + Lambda — captures item changes in a stream; Lambda processes change records' }, { id: 'C', text: 'SQS polling of DynamoDB' }, { id: 'D', text: 'EventBridge events from DynamoDB' }], correct: ['B'], explanation: 'DynamoDB Streams captures a time-ordered sequence of item changes (INSERT, MODIFY, REMOVE). Configure a Lambda function as an event source for the stream — Lambda is invoked with batches of change records.', distractors: { A: 'There\'s no DynamoDB "scheduled queries" feature — Streams + Lambda is the event-driven pattern.', C: 'SQS is a message queue — DynamoDB doesn\'t push to SQS directly.', D: 'DynamoDB events in EventBridge are available but DynamoDB Streams + Lambda is the native, lower-latency pattern.' } },
  { id: 'd3-db-026', domain: 3, topics: ['RDS', 'instance type', 'memory'], type: 'single', stem: 'An RDS PostgreSQL database with a 200 GB dataset frequently reads from disk (cache miss ratio is high). What is the most effective performance improvement?', options: [{ id: 'A', text: 'Add read replicas' }, { id: 'B', text: 'Upgrade to a memory-optimized instance type (R class) — larger shared_buffers cache more of the working dataset in RAM' }, { id: 'C', text: 'Enable Multi-AZ' }, { id: 'D', text: 'Increase EBS IOPS' }], correct: ['B'], explanation: 'High cache miss ratio (reading from disk) means the working dataset doesn\'t fit in memory (shared_buffers). Upgrading to an R-class instance (more RAM) allows PostgreSQL to cache more data in shared_buffers, dramatically reducing disk I/O.', distractors: { A: 'Read replicas distribute read load — but each replica also has the same memory constraint.', C: 'Multi-AZ provides HA — doesn\'t improve cache efficiency.', D: 'More IOPS handles the disk reads faster — but doesn\'t eliminate the reads. More memory eliminates the reads.' } },
  { id: 'd3-db-027', domain: 3, topics: ['DynamoDB', 'conditional writes', 'optimistic locking'], type: 'single', stem: 'Two Lambda functions might update the same DynamoDB item simultaneously, causing a lost update. What DynamoDB feature prevents overwrites of stale data?', options: [{ id: 'A', text: 'DynamoDB Transactions' }, { id: 'B', text: 'Conditional writes — include a condition (e.g., version number check) that fails if another writer modified the item first' }, { id: 'C', text: 'DynamoDB Streams' }, { id: 'D', text: 'DynamoDB Multi-AZ replication' }], correct: ['B'], explanation: 'Conditional writes implement optimistic locking: include condition_expression="version = :expected_version". If another Lambda incremented the version first, the condition fails and the write is rejected. The failed Lambda retries with fresh data.', distractors: { A: 'Transactions are atomic multi-item operations — conditional writes handle single-item optimistic locking more efficiently.', C: 'Streams capture changes after they happen — not a write prevention mechanism.', D: 'Multi-AZ replication is for data durability — not write conflict prevention.' } },
  { id: 'd3-db-028', domain: 3, topics: ['Keyspaces', 'Cassandra', 'managed'], type: 'single', stem: 'A company runs an Apache Cassandra cluster and wants to migrate to a managed AWS service without changing their Cassandra application code (CQL queries). Which service is compatible?', options: [{ id: 'A', text: 'Amazon DynamoDB' }, { id: 'B', text: 'Amazon Keyspaces (for Apache Cassandra) — serverless, Cassandra-compatible, CQL queries work unchanged' }, { id: 'C', text: 'Amazon RDS' }, { id: 'D', text: 'Amazon Aurora' }], correct: ['B'], explanation: 'Amazon Keyspaces is a serverless, Cassandra-compatible managed database. Existing Cassandra applications using CQL work without code changes. No cluster management, automatic scaling, and durable storage with three-AZ replication.', distractors: { A: 'DynamoDB uses its own API — not CQL compatible. Application code would need rewriting.', C: 'RDS runs relational databases (MySQL, PostgreSQL, etc.) — not Cassandra-compatible.', D: 'Aurora runs MySQL/PostgreSQL — not Cassandra.' } },
  { id: 'd3-db-029', domain: 3, topics: ['Timestream', 'time-series', 'IoT'], type: 'single', stem: 'An IoT platform ingests 10 million data points per minute from sensors. Queries analyze time-series trends (e.g., last 24 hours by device). Which AWS database is purpose-built for this?', options: [{ id: 'A', text: 'DynamoDB with timestamp sort key' }, { id: 'B', text: 'Amazon Timestream — serverless time-series database optimized for IoT and monitoring data' }, { id: 'C', text: 'RDS with time-series schema' }, { id: 'D', text: 'S3 + Athena for time-series queries' }], correct: ['B'], explanation: 'Amazon Timestream is purpose-built for time-series data: automatic data tiering (recent data in memory, historical in magnetic storage), built-in time-series functions (interpolation, smoothing), and scales to trillions of events per day.', distractors: { A: 'DynamoDB can store time-series data but lacks time-series-specific query functions and automatic data tiering.', C: 'RDS can store time-series but doesn\'t scale to millions of data points per minute without significant schema and query optimization.', D: 'S3 + Athena provides ad-hoc analytics but lacks real-time ingestion at 10M events/minute performance.' } },
  { id: 'd3-db-030', domain: 3, topics: ['Aurora', 'backtrack', 'performance'], type: 'single', stem: 'An Aurora MySQL cluster has backtrack enabled with a 24-hour window. A bad query deleted important rows at 3 PM. At 4 PM, the team wants to recover. What is the fastest recovery option?', options: [{ id: 'A', text: 'Restore from PITR to a new cluster (takes 30-60 minutes)' }, { id: 'B', text: 'Aurora Backtrack — rewind the existing cluster to 2:59 PM in minutes without creating a new cluster' }, { id: 'C', text: 'Restore from the daily snapshot' }, { id: 'D', text: 'Query the Aurora read replica before it replicates the delete' }], correct: ['B'], explanation: 'Aurora Backtrack rewinds the cluster in-place to the specified time (within the backtrack window). It takes minutes and the same cluster endpoint is used — no DNS update or application change needed. Much faster than PITR.', distractors: { A: 'PITR creates a new cluster which takes longer and requires connection string updates.', C: 'Daily snapshot would restore to yesterday\'s state — losing all of today\'s legitimate data.', D: 'Aurora replicas share the same cluster storage — the delete is immediately visible on all replicas.' } },
  { id: 'd3-db-031', domain: 3, topics: ['DynamoDB', 'Accelerator', 'DAX', 'consistency'], type: 'single', stem: 'An application uses DAX in front of DynamoDB. After writing an item to DynamoDB, an immediate read returns stale data. What explains this?', options: [{ id: 'A', text: 'DynamoDB is eventually consistent' }, { id: 'B', text: 'DAX caches reads — a cached version of the item may be served until the TTL expires or the cache is invalidated by a write through DAX' }, { id: 'C', text: 'The write was not committed' }, { id: 'D', text: 'DAX doesn\'t support strongly consistent reads' }], correct: ['B'], explanation: 'DAX maintains an item cache. If a read hits the cache before the write updates it, stale data is returned. For writes through DAX, the cache is updated. For writes directly to DynamoDB (bypassing DAX), the DAX cache may return stale data until TTL expires.', distractors: { A: 'DynamoDB itself is strongly consistent for reads from the same region — DAX adds the caching layer.', C: 'The write committed successfully — the issue is DAX cache staleness.', D: 'DAX does support strongly consistent reads with the Strongly Consistent Read API — they bypass the item cache.' } },
  { id: 'd3-db-032', domain: 3, topics: ['Neptune', 'graph database', 'use cases'], type: 'single', stem: 'A company builds a social network where queries traverse "friends of friends" relationships (multi-hop graph queries). Which database type is optimized for this?', options: [{ id: 'A', text: 'RDS MySQL with JOIN queries' }, { id: 'B', text: 'Amazon Neptune — purpose-built graph database using Gremlin/SPARQL/openCypher for graph traversal queries' }, { id: 'C', text: 'DynamoDB with relationship tables' }, { id: 'D', text: 'ElastiSearch for graph queries' }], correct: ['B'], explanation: 'Graph databases (Neptune) are optimized for highly connected data and multi-hop traversals. "Friends of friends of friends" requires multiple JOINs in SQL (exponential complexity) but is native and efficient in graph databases.', distractors: { A: 'Multi-hop JOINs in SQL become exponentially expensive as hop count increases — graph databases are O(relationship count), not O(table size).', C: 'DynamoDB can store relationship data but traversal requires multiple round trips and application-level logic.', D: 'ElasticSearch is a search and analytics engine — not a graph database.' } },
  { id: 'd3-db-033', domain: 3, topics: ['Redshift', 'AQUA', 'query acceleration'], type: 'single', stem: 'A Redshift cluster is running complex analytical queries on petabytes of data. Query execution is slow because data has to be transferred from storage to compute. What Redshift feature reduces this bottleneck?', options: [{ id: 'A', text: 'Redshift Serverless' }, { id: 'B', text: 'AQUA (Advanced Query Accelerator) — distributed hardware-accelerated cache layer near the storage; reduces data transfer to compute nodes' }, { id: 'C', text: 'Redshift Spectrum' }, { id: 'D', text: 'Materialized Views' }], correct: ['B'], explanation: 'AQUA is a distributed cache near Redshift Managed Storage. It executes computation and filtering locally (near the data) before sending results to compute nodes, dramatically reducing data transfer and query latency for large analytical queries.', distractors: { A: 'Redshift Serverless manages capacity automatically — not a query acceleration layer.', C: 'Redshift Spectrum queries data in S3 — not a compute/storage bandwidth optimization.', D: 'Materialized Views pre-compute and cache query results — good for repeated queries but doesn\'t address the data transfer bottleneck during query execution.' } },
  { id: 'd3-db-034', domain: 3, topics: ['DynamoDB', 'access patterns', 'single table design'], type: 'single', stem: 'A DynamoDB-based e-commerce application needs to query: "all orders for a customer" and "all items in an order" efficiently. What design approach enables both access patterns?', options: [{ id: 'A', text: 'Create separate tables for customers, orders, and items — use DMS to join them' }, { id: 'B', text: 'Single-table design with overloaded partition key (CustomerId) and sort key (ORDER#orderId, ITEM#itemId) — both patterns served by key structure' }, { id: 'C', text: 'Use DynamoDB Scan for all queries' }, { id: 'D', text: 'Create a GSI for every access pattern' }], correct: ['B'], explanation: 'DynamoDB single-table design packs multiple entity types in one table: PK=CustomerId, SK=ORDER#orderId for orders, SK=ITEM#orderId#itemId for items. Query by PK to get all customer orders; Query with PK filter by SK prefix to get items within an order.', distractors: { A: 'DynamoDB doesn\'t support JOINs — multiple tables require application-level joins with N+1 query problems.', C: 'Scans are O(n) — efficient query design avoids scans.', D: 'One GSI per access pattern is sometimes needed but single-table design reduces the need for multiple GSIs.' } },
  { id: 'd3-db-035', domain: 3, topics: ['OpenSearch', 'full-text search', 'Elasticsearch'], type: 'single', stem: 'A product catalog stored in DynamoDB needs full-text search capability (fuzzy matching, relevance scoring). DynamoDB doesn\'t support this natively. What architecture adds search?', options: [{ id: 'A', text: 'Use DynamoDB GSI for full-text search' }, { id: 'B', text: 'Stream DynamoDB changes via DynamoDB Streams → Lambda → Amazon OpenSearch Service for full-text indexing' }, { id: 'C', text: 'Use Athena to query DynamoDB with LIKE queries' }, { id: 'D', text: 'Move the catalog to RDS for full-text search' }], correct: ['B'], explanation: 'DynamoDB Streams → Lambda → OpenSearch is the canonical pattern for adding search to DynamoDB data. Lambda processes stream records and indexes items in OpenSearch. Search queries go to OpenSearch; transactional reads/writes go to DynamoDB.', distractors: { A: 'GSIs support exact key lookups and range queries — not full-text search, fuzzy matching, or relevance scoring.', C: 'Athena queries S3 data — not DynamoDB. And LIKE queries don\'t provide relevance scoring.', D: 'Moving to RDS solves search but RDS full-text search (FULLTEXT indexes in MySQL) has limitations vs. OpenSearch for large-scale search.' } },
  { id: 'd3-db-036', domain: 3, topics: ['ElastiCache', 'eviction', 'policy'], type: 'single', stem: 'An ElastiCache Redis cache is running near memory capacity. New items need to be added. What eviction policy removes the least recently used items when memory is full?', options: [{ id: 'A', text: 'noeviction — throws errors when memory is full' }, { id: 'B', text: 'allkeys-lru — evicts least recently used keys from the entire key space when memory limit is reached' }, { id: 'C', text: 'volatile-lru — evicts LRU keys only from keys with TTL set' }, { id: 'D', text: 'allkeys-random — evicts random keys' }], correct: ['B'], explanation: 'allkeys-lru evicts the least recently used keys across all keys when memory limit is reached. Best for caches where all data can be re-fetched from the source if evicted. Most common cache eviction policy.', distractors: { A: 'noeviction is for when Redis is used as a primary store (not cache) — errors are not acceptable for a cache.', C: 'volatile-lru only evicts keys with TTL — keys without TTL never get evicted, limiting effectiveness.', D: 'allkeys-random evicts random keys — not optimal because recently accessed (hot) keys might be evicted.' } },
  { id: 'd3-db-037', domain: 3, topics: ['Aurora', 'machine learning', 'SQL'], type: 'single', stem: 'A data analyst wants to run sentiment analysis on customer reviews stored in Aurora PostgreSQL without exporting data or writing Python code. What Aurora feature enables this?', options: [{ id: 'A', text: 'Aurora Lambda integration' }, { id: 'B', text: 'Aurora ML integration — call Amazon Comprehend or SageMaker models directly from SQL queries' }, { id: 'C', text: 'Export to S3 and run Comprehend in batch' }, { id: 'D', text: 'Redshift ML for PostgreSQL' }], correct: ['B'], explanation: 'Aurora ML integration provides SQL functions that call SageMaker (for custom models) and Amazon Comprehend (NLP: sentiment, entity extraction, language detection). Call aws_comprehend.detect_sentiment() in a SQL SELECT statement.', distractors: { A: 'Aurora Lambda integration calls custom Lambda functions — not ML services with SQL syntax.', C: 'Export to S3 and batch process works but requires external orchestration — Aurora ML keeps the workflow in SQL.', D: 'Redshift ML is for Redshift data warehouse — not for Aurora PostgreSQL.' } },
  { id: 'd3-db-038', domain: 3, topics: ['DynamoDB', 'export', 'S3', 'analytics'], type: 'single', stem: 'A team wants to analyze historical DynamoDB data in Amazon Athena without impacting the production DynamoDB table. What built-in feature enables this?', options: [{ id: 'A', text: 'DynamoDB Scan and write to S3 manually' }, { id: 'B', text: 'DynamoDB Export to S3 — exports table data to S3 in JSON/ION/Parquet format for Athena queries, no table impact' }, { id: 'C', text: 'DynamoDB Streams to S3 via Kinesis' }, { id: 'D', text: 'AWS Glue ETL from DynamoDB' }], correct: ['B'], explanation: 'DynamoDB Export to S3 (point-in-time export) exports the full table to S3 in DynamoDB JSON, ION, or Parquet format without consuming read capacity or impacting performance. Query the exported data with Athena.', distractors: { A: 'Manual scan exports read from the table — consumes RCUs and takes time.', C: 'Streams + Kinesis provides continuous data pipeline — appropriate for streaming but not clean historical snapshots.', D: 'AWS Glue DynamoDB connector works but DynamoDB Export is simpler and doesn\'t consume RCUs.' } },
  { id: 'd3-db-039', domain: 3, topics: ['RDS', 'storage autoscaling', 'resize'], type: 'single', stem: 'How does RDS Storage Auto Scaling determine when to increase storage?', options: [{ id: 'A', text: 'RDS increases storage every week by a fixed amount' }, { id: 'B', text: 'When free storage is less than 10% of allocated storage AND the low storage condition has lasted for 5+ minutes AND 6+ hours since last expansion' }, { id: 'C', text: 'When any storage write fails due to space constraints' }, { id: 'D', text: 'When CloudWatch storage alarm fires' }], correct: ['B'], explanation: 'RDS Storage Auto Scaling triggers when: (1) free storage < 10% of allocated, (2) low storage has lasted ≥5 minutes, AND (3) ≥6 hours have passed since the last auto scaling. Storage increases by max of 5 GB, 10% of allocated, or 7x daily I/O.', distractors: { A: 'RDS storage scaling is reactive to actual usage — not on a fixed weekly schedule.', C: 'RDS doesn\'t wait for write failures — it proactively scales before running out.', D: 'Storage Auto Scaling is built-in — not triggered by external CloudWatch alarms.' } },
  { id: 'd3-db-040', domain: 3, topics: ['DynamoDB', 'global tables', 'replication'], type: 'single', stem: 'A company uses DynamoDB Global Tables. A write occurs in us-east-1. How long does it typically take for the change to be visible in eu-west-1?', options: [{ id: 'A', text: 'Immediately — DynamoDB Global Tables uses synchronous replication' }, { id: 'B', text: 'Typically within 1 second — asynchronous replication using DynamoDB Streams' }, { id: 'C', text: '5-10 minutes' }, { id: 'D', text: 'Dependent on the DynamoDB Streams retention period (24 hours max)' }], correct: ['B'], explanation: 'DynamoDB Global Tables replicates within typically under 1 second (often milliseconds) using an asynchronous process driven by DynamoDB Streams. RPO is approximately 1 second for normal operation.', distractors: { A: 'DynamoDB Global Tables uses asynchronous replication — not synchronous. Synchronous would add cross-region write latency to every operation.', C: '5-10 minutes is far too slow for DynamoDB Global Tables — typical replication is sub-second.', D: 'Streams retention (24 hours) is not the replication delay — it\'s how long streams records are retained for processing.' } },
  { id: 'd3-db-041', domain: 3, topics: ['Redshift', 'spectrum', 'data lake'], type: 'single', stem: 'A company has 5 PB of historical data in S3 and 100 GB in a Redshift cluster. They want to query both together using SQL. What enables this without loading S3 data into Redshift?', options: [{ id: 'A', text: 'Redshift COPY command for S3 data' }, { id: 'B', text: 'Redshift Spectrum — extends Redshift queries to S3 data lake without loading; queries both Redshift and S3 in one SQL statement' }, { id: 'C', text: 'Athena for the S3 data' }, { id: 'D', text: 'Glue crawler on S3 and Redshift' }], correct: ['B'], explanation: 'Redshift Spectrum uses a fleet of Spectrum nodes to query data in S3 directly. Define external tables (catalog in Glue/Redshift external schema) pointing to S3. JOIN Redshift tables with S3 data in one query — Redshift handles the execution plan.', distractors: { A: 'COPY loads data into Redshift — storing 5 PB in Redshift would be very expensive.', C: 'Athena queries S3 but doesn\'t federate with Redshift tables in the same query.', D: 'Glue crawler creates catalog metadata — doesn\'t enable Redshift + S3 JOIN queries.' } },
  { id: 'd3-db-042', domain: 3, topics: ['DynamoDB', 'capacity', 'RCU calculation'], type: 'single', stem: 'A DynamoDB table needs to handle 5,000 eventually consistent reads per second, each reading items of 8 KB. How many RCUs are required?', options: [{ id: 'A', text: '5,000 RCUs' }, { id: 'B', text: '10,000 RCUs' }, { id: 'C', text: '20,000 RCUs' }, { id: 'D', text: 'RCU = (item size KB / 4) × (0.5 for eventually consistent) × ops/sec = (8/4) × 0.5 × 5,000 = 5,000 RCUs' }], correct: ['D'], explanation: 'Eventually consistent read: 0.5 RCU per 4 KB. For 8 KB item: 8/4 = 2 × 0.5 = 1 RCU per read. For 5,000 reads/sec: 5,000 RCUs. The formula: RCUs = ceil(item_size/4) × 0.5 (eventually consistent) × reads/sec.', distractors: { A: '5,000 RCUs: This is correct! An 8 KB item with eventually consistent reads = 1 RCU per read × 5,000 = 5,000. Answer D explains the calculation correctly.', B: '10,000 would be for strongly consistent reads (1 RCU per 4 KB × 2 = 2 RCUs per 8 KB item × 5,000 = 10,000).', C: '20,000 would be for strongly consistent reads of 16 KB items.' } },
  { id: 'd3-db-043', domain: 3, topics: ['Redshift', 'distribution styles'], type: 'single', stem: 'A Redshift table is joined frequently with a small dimension table (1,000 rows). Query performance is slow due to data movement during joins. What distribution style for the dimension table minimizes data movement?', options: [{ id: 'A', text: 'KEY distribution — distribute by the join key' }, { id: 'B', text: 'ALL distribution — copy the small dimension table to every compute node' }, { id: 'C', text: 'EVEN distribution — distribute rows evenly' }, { id: 'D', text: 'AUTO distribution' }], correct: ['B'], explanation: 'For small dimension tables (frequently joined), ALL distribution copies the entire table to every node. JOIN operations find the dimension data locally on each node — no data movement (broadcast join). Suitable for tables under ~3 million rows.', distractors: { A: 'KEY distribution co-locates rows with the same join key — requires both tables to be distributed on the same key, which may not reduce data movement for dimension tables.', C: 'EVEN distribution spreads rows randomly — joins require moving data across nodes.', D: 'AUTO lets Redshift choose — may choose ALL for small tables but explicit control is better for optimization.' } },
  { id: 'd3-db-044', domain: 3, topics: ['Aurora', 'connection management', 'proxy'], type: 'single', stem: 'An Aurora PostgreSQL cluster receives 10,000 concurrent application connections. The cluster starts experiencing high connection overhead. What service reduces this?', options: [{ id: 'A', text: 'Increase Aurora max_connections parameter' }, { id: 'B', text: 'Amazon RDS Proxy — pools and multiplexes connections, reducing actual connections from 10,000 to a smaller pool' }, { id: 'C', text: 'Add more Aurora read replicas' }, { id: 'D', text: 'Enable Aurora Serverless v2' }], correct: ['B'], explanation: 'RDS Proxy maintains a pool of long-lived connections to the Aurora cluster. The 10,000 application connections connect to Proxy (fast, low-overhead). Proxy maintains a much smaller pool of actual database connections. Reduces connection establishment overhead and memory consumption.', distractors: { A: 'Increasing max_connections allows more connections but each still consumes DB memory (~5-10MB per PostgreSQL connection).', C: 'Read replicas add capacity for reads but don\'t reduce write connection overhead.', D: 'Serverless v2 scales compute — doesn\'t reduce the number of connections to the database.' } },
  { id: 'd3-db-045', domain: 3, topics: ['DynamoDB', 'table class', 'Standard IA'], type: 'single', stem: 'A DynamoDB table stores compliance audit logs that are rarely queried but must be retained for 7 years. How can storage costs be reduced for this low-access table?', options: [{ id: 'A', text: 'Move to S3 instead of DynamoDB' }, { id: 'B', text: 'Switch to DynamoDB Standard-IA table class — reduces storage costs by ~60% for tables with infrequent access' }, { id: 'C', text: 'Delete old items after they expire' }, { id: 'D', text: 'Use DynamoDB Streams to archive to S3' }], correct: ['B'], explanation: 'DynamoDB Standard-IA (Infrequent Access) table class reduces storage costs by ~60% vs. Standard. Higher read/write costs (not significant for rarely queried tables). Ideal for long-term retention tables like compliance logs, audit trails.', distractors: { A: 'Moving to S3 means losing DynamoDB query capabilities — if audit queries are needed, DynamoDB Standard-IA is better.', C: 'Deleting items violates the 7-year retention requirement.', D: 'Archiving to S3 via Streams works but DynamoDB Standard-IA is simpler if the data should remain queryable.' } },
]
